"""
    Ritorna True se tutti i dati passati non sono None o stringa vuota
    """
def check_required_data(dati: tuple) -> bool {
    result = True;
    for elem in dati {
        if (elem is None) {
            result = False;
            break;
        }
        tmp = elem.strip(' \n\r');
        if (tmp == '') {
            result = False;
            break;
        }
    }
    return result;
}

